// ClassifyAsset embebido (ver docs/anexo_e_f_v2.md para la justificacion de pesos)
const SERVICE_WEIGHTS = {
  21: 7, 22: 9, 23: 12, 25: 4, 80: 5, 161: 6, 389: 7, 443: 4,
  445: 8, 587: 4, 3306: 11, 5432: 11, 6379: 11, 8080: 5,
};

function classifyAsset(openPorts) {
  const score = (openPorts || []).reduce((sum, port) => sum + (SERVICE_WEIGHTS[port] || 1), 0);
  let classification;
  if (score > 20) classification = 'Critico';
  else if (score > 10) classification = 'Alto';
  else classification = 'Normal';
  return { score, classification };
}

// Alcance del sistema: solo direcciones IPv4 de host de la subred del laboratorio
// (172.20.0.1 a 172.20.0.254). El cuerpo del POST a /webhook/nmap llega de
// afuera, asi que se valida antes de clasificar: si un solo elemento no cumple,
// se rechaza la peticion entera y nada llega a Greenbone.
const LAB_IP = /^172\.20\.0\.(?:[1-9]\d?|1\d\d|2[0-4]\d|25[0-4])$/;
function assertHost(h) {
  if (!h || typeof h !== 'object' || typeof h.ip !== 'string' || !LAB_IP.test(h.ip)) {
    const dato = JSON.stringify(h && typeof h === 'object' ? h.ip : h);
    throw new Error(`Host fuera de alcance (solo IPv4 de 172.20.0.1 a 172.20.0.254): ${String(dato).slice(0, 80)}`);
  }
  const ports = h.ports === undefined ? [] : h.ports;
  if (!Array.isArray(ports) || ports.some(p => !Number.isInteger(p) || p < 1 || p > 65535)) {
    throw new Error(`Puertos invalidos para ${h.ip}: se esperan enteros de 1 a 65535`);
  }
}

const raw = items[0].json;
// n8n guarda el body bajo $json.body cuando recibe application/json
const payload = raw && raw.hosts !== undefined ? raw : raw && raw.body !== undefined ? raw.body : raw;
// "hosts" es obligatorio y tiene que ser una lista. Una lista vacia es una red
// limpia (el nodo NmapScan la envia cuando no descubre hosts); sin "hosts", con
// un "hosts" que no es una lista o mas larga que la subred, la peticion esta mal
// formada y se rechaza: no se informa "red limpia" por un cuerpo equivocado.
if (!payload || typeof payload !== 'object' || !Array.isArray(payload.hosts)) {
  throw new Error('Peticion mal formada: hosts debe ser una lista');
}
const hostsRaw = payload.hosts;
if (hostsRaw.length > 254) {
  throw new Error('Peticion mal formada: la subred del laboratorio tiene 254 direcciones de host');
}

const ignoradas = ["172.20.0.1", "172.20.0.2", "172.20.0.3"];

// Soporta formato viejo (array de strings, solo IP) y nuevo (array de {ip, ports})
// para no romper compatibilidad si algun caller viejo todavia manda solo IPs.
const hosts = hostsRaw.map(h => (typeof h === 'string') ? { ip: h, ports: [] } : h);
hosts.forEach(assertHost);
// Una direccion repetida cuenta una sola vez (la primera).
const enAlcance = hosts.filter((h, i) => ignoradas.indexOf(h.ip) === -1 && hosts.findIndex(x => x.ip === h.ip) === i);

const clasificados = enAlcance.map(h => {
  // Un puerto repetido cuenta una sola vez: no suma puntaje dos veces.
  const ports = [...new Set(h.ports || [])];
  const { score, classification } = classifyAsset(ports);
  return { ip: h.ip, ports, score, classification };
});

// OE4: solo Alto y Critico pasan al analisis profundo de Greenbone.
// Los Normales quedan excluidos por diseno (no es un bug, es la priorizacion declarada).
const objetivo = clasificados.filter(h => h.classification === 'Alto' || h.classification === 'Critico');
const normales = clasificados.filter(h => h.classification === 'Normal');

if (objetivo.length === 0) {
  return [{ json: {
    all_ips: "", ip_objetivo: "", cantidad_hosts: 0, encontrados: false,
    clasificacion: clasificados, objetivo: [], normales
  } }];
}

const lista = objetivo.map(h => h.ip).join(", ");
return [{ json: {
  all_ips: lista,
  ip_objetivo: lista,
  cantidad_hosts: objetivo.length,
  encontrados: true,
  clasificacion: clasificados,
  objetivo,
  normales
} }];

