const SCAN_CONFIGS = [
  '8715c877-47a0-438d-98a3-27c7a6ab2196', // Discovery
  'daba56c8-73ec-11df-a475-002264764cea', // Full and fast
];

// 1. Get the previous output (Target Creation Result)
const prevOutput = items[0].json.stdout;

// 2. Extract the Target ID using Regex
const match = prevOutput.match(/id="([^"]+)"/);
const targetId = match ? match[1] : null;

if (!targetId || !UUID.test(targetId)) {
  throw new Error("Could not find Target ID in previous output");
}

// 3. Get the IP list from the earlier 'ClassifyAssets' node
const ipObjetivo = $('ClassifyAssets').first().json.ip_objetivo;
if (typeof ipObjetivo !== 'string' || !ipObjetivo.split(', ').every(isAllowedIp)) {
  throw new Error('CreateTask: la lista de hosts no es una lista de IPv4 de 172.20.0.0/24');
}

// 4. Read scan config from launcher (passed as webhook query param)
// El disparo puede venir de 3 fuentes: Webhook Nmap (externo), Webhook Escaneo
// Interno (launcher, escaneo del lab), o Manual Trigger (sin query params en
// absoluto). Se prueban en orden y se cae al perfil de descubrimiento rapido
// solo si ninguno aporto scan_config.
let configId;
for (const hook of ['Webhook Nmap', 'Webhook Escaneo Interno']) {
  try {
    configId = $(hook).first().json.query?.scan_config;
  } catch (e) {
    configId = undefined;
  }
  if (configId !== undefined && configId !== '') break;
}
if (configId === undefined || configId === '') {
  configId = '8715c877-47a0-438d-98a3-27c7a6ab2196';
} else if (!SCAN_CONFIGS.includes(configId)) {
  throw new Error('CreateTask: scan_config no es uno de los perfiles admitidos');
}

// 5. Construct Command
const xml = `<create_task><name>Scan ${ipObjetivo}</name><config id='${configId}'/><target id='${targetId}'/><scanner id='08b69003-5fc2-4037-a479-93b440211c73'/></create_task>`;

try {
  const stdout = execFileSync(GVM_CLI, [...GMP_ARGS, xml]).toString();
  return [{ json: { stdout } }];
} catch (error) {
  throw new Error(error.message);
}

