const { execFile } = require('child_process');

// gvm-cli recibe el XML como un unico argumento (arreglo de argumentos, sin
// shell): ningun caracter del XML puede interpretarse como una orden.
const GVM_CLI = '/home/node/gvm-env/bin/gvm-cli';
const GMP_ARGS = ['--gmp-username', 'admin', '--gmp-password', 'admin123', 'socket', '--socketpath', '/run/gvmd/gvmd.sock', '--xml'];
const UUID = /^[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}$/;

// execFile con timeout de 30s por llamada para evitar que gvm-cli se cuelgue
const gmp = (xml) => new Promise((resolve, reject) => {
  execFile(GVM_CLI, [...GMP_ARGS, xml], { timeout: 30000 }, (error, stdout) => {
    if (error) reject(error);
    else resolve({ stdout });
  });
});
const sleep = (ms) => new Promise(resolve => setTimeout(resolve, ms));

const createTaskOutput = $('CreateTask').first().json.stdout;
const taskMatch = createTaskOutput.match(/id="([^"]+)"/);
const taskId = taskMatch ? taskMatch[1] : null;

if (!taskId || !UUID.test(taskId)) {
  throw new Error('No se pudo obtener el Task ID para verificar el estado del escaneo');
}

const MAX_WAIT_MS = 90 * 60 * 1000; // 90 minutos en tiempo de reloj real
const POLL_INTERVAL = 60000; // 60 segundos entre consultas

const startTime = Date.now();

while (Date.now() - startTime < MAX_WAIT_MS) {
  const { stdout: output } = await gmp(`<get_tasks task_id='${taskId}'/>`);
  const statusMatch = output.match(/<status>([^<]+)<\/status>/);
  const status = statusMatch ? statusMatch[1] : 'Unknown';

  if (status === 'Done') {
    return [{ json: { stdout: $('StartTask').first().json.stdout, timed_out: false, scan_status: 'Done' } }];
  }

  if (status === 'Stopped' || status === 'Interrupted') {
    return [{ json: { timed_out: true, task_id: taskId, scan_status: status, motivo: `Escaneo termino con estado ${status}` } }];
  }

  await sleep(POLL_INTERVAL);
}

// Timeout alcanzado: retornamos flag en vez de lanzar error para poder notificar por Telegram
return [{ json: { timed_out: true, task_id: taskId, scan_status: 'Timeout', motivo: 'Supero los 90 minutos' } }];

