// 1. Obtenemos todos los resultados crudos
// El item centinela del nodo de parseo (analisis sin hallazgos) no es un hallazgo.
const centinela = items.map(item => item.json).find(v => v.sin_hallazgos) || {};
const vulns = items.map(item => item.json).filter(v => !v.sin_hallazgos);


// --- HELPERS ---
// El nombre, la descripcion y la solucion de cada hallazgo vienen del reporte de
// Greenbone, que a su vez refleja lo que respondio el activo escaneado: se
// escapan antes de insertarlos en el HTML del correo.
const esc = (val) => String(val).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const toText = (val) => {
    if (!val) return "N/A";
    if (typeof val === 'string') return val;
    if (typeof val === 'object' && val._) return val._;
    return JSON.stringify(val);
};

const getIP = (v) => {
    if (v.host && v.host._) return v.host._;
    if (typeof v.host === 'string') return v.host;
    return "Desconocido";
};

// 2. Lógica Multi-Host
// Sin hallazgos, los hosts del reporte son los activos que se enviaron a Greenbone.
const uniqueHosts = vulns.length
  ? [...new Set(vulns.map(v => getIP(v)))]
  : String($('ClassifyAssets').first().json.all_ips || '').split(',').map(s => s.trim()).filter(Boolean);
const hostsString = uniqueHosts.join(', ');

const scanDate = (vulns[0] && vulns[0].timestamp) || centinela.timestamp || new Date().toISOString();

// 3. Estadísticas Globales
const critical = vulns.filter(v => v.severity >= 9.0);
const high = vulns.filter(v => v.severity >= 7.0 && v.severity < 9.0);
const medium = vulns.filter(v => v.severity >= 4.0 && v.severity < 7.0);
const low = vulns.filter(v => v.severity < 4.0);

// 4. Armado del HTML
const htmlReport = `
