`;

return [{
  json: {
    email_body: htmlReport,
    subject: `Reporte de Red (${uniqueHosts.length} Hosts) - ${critical.length > 0 ? '🔴 CRITICO' : vulns.length === 0 ? '🟢 SIN HALLAZGOS' : '🔵 INFO'}`,
    hosts_string: hostsString,
    scan_date: scanDate,
    total_hallazgos: vulns.length,
    critical_count: critical.length,
    high_count: high.length,
    medium_count: medium.length,
    low_count: low.length
  }
}];

const reportData = items[0].json;

// Item centinela de un analisis sin hallazgos (ver el final del nodo).
const sinHallazgos = () => {
  const report = (reportData && reportData.get_reports_response && reportData.get_reports_response.report) || {};
  return { json: { sin_hallazgos: true, scan_id: report.id || null, timestamp: report.creation_time || null } };
};

// Un reporte que no tiene la seccion de resultados no se pudo leer (respuesta
// de error de GMP, reporte incompleto): no es un analisis sin hallazgos. El nodo
// falla, la ejecucion queda en error y la tarea sigue en Greenbone para revisarla.
const results = reportData && reportData.get_reports_response && reportData.get_reports_response.report
  && reportData.get_reports_response.report.report && reportData.get_reports_response.report.report.results;
if (results === undefined || results === null) {
  throw new Error('No se pudo leer el reporte de Greenbone: la respuesta no tiene la seccion de resultados');
}
let rawResults = results.result;

// Bug corregido: si el escaneo no encuentra nada, "results" existe pero sin
// la propiedad "result" (no es un array vacio, es undefined). El codigo
// original lo envolvia en [undefined] y reventaba al leer vuln.host.
if (!rawResults) {
  rawResults = [];
} else if (!Array.isArray(rawResults)) {
  rawResults = [rawResults];
}

const cleanVulnerabilities = rawResults.map(vuln => {
  return {
    json: {
      scan_id: reportData.get_reports_response.report.id,
      timestamp: reportData.get_reports_response.report.creation_time,
      host: (vuln.host && vuln.host['#text']) || (vuln.host && vuln.host._) || vuln.host || 'Desconocido',
      port: vuln.port,
      severity: parseFloat(vuln.severity),
      name: vuln.name,
      description: vuln.description,
      cve: (() => { const refs = vuln.nvt?.refs?.ref; const arr = !refs ? [] : (Array.isArray(refs) ? refs : [refs]); const cves = arr.filter(r => r && r.type === 'cve').map(r => r.id); return cves.length ? cves.join(', ') : (vuln.nvt?.cve || 'N/A'); })(),
      solution: vuln.nvt?.solution || 'No solution provided',
      solution_type: vuln.nvt?.solution_type || 'Unspecified'
    }
  };
});

const hallazgos = cleanVulnerabilities.filter(item => item.json.severity > 0.0);
// Un nodo que no devuelve items corta el flujo en n8n: sin hallazgos de
// severidad mayor que 0 no habria reporte final, correo ni limpieza. Se
// devuelve un item centinela y el nodo siguiente arma el reporte "sin hallazgos".
if (hallazgos.length === 0) return [sinHallazgos()];
return hallazgos;

