const { execFile } = require('child_process');

// Subred fija del laboratorio (ver lab-targets/docker-compose.lab-targets.yml).
// No se usa $env/process.env: el sandbox del JS Task Runner de n8n bloquea
// el acceso a variables de entorno en Code nodes por defecto.
const subnet = '172.20.0.0/24';
const relevantPorts = 'T:21,22,23,25,80,389,443,445,587,3306,5432,6379,8080,U:161';

// nmap se invoca con arreglo de argumentos, sin shell, y de forma asincronica.
// El escaneo de puertos del laboratorio tarda mas que el heartbeat del Task
// Runner (N8N_RUNNERS_HEARTBEAT_INTERVAL=120 s): una llamada sincronica bloquea
// el event loop del runner, que deja de responder, y n8n aborta la tarea.
const nmap = (args) => new Promise((resolve, reject) => {
  execFile('nmap', args, { maxBuffer: 1024 * 1024 * 20 }, (error, stdout) => {
    if (error) reject(error);
    else resolve(stdout.toString());
  });
});

// 1. Descubrimiento (host vivo / muerto)
const discoveryXml = await nmap(['-sn', '-n', '-oX', '-', subnet]);
const discBlocks = discoveryXml.match(/<host[\s>][\s\S]*?<\/host>/g) || [];
const upIps = [];
for (const block of discBlocks) {
  if (/<status state="up"/.test(block)) {
    const m = block.match(/addr="([\d.]+)" addrtype="ipv4"/);
    if (m) upIps.push(m[1]);
  }
}

if (upIps.length === 0) {
  return [{ json: { hosts: [], subnet, hostCount: 0 } }];
}

// 2. Escaneo de puertos relevantes (los catalogados en SERVICE_WEIGHTS, ver
//    docs/anexo_e_f_v2.md) sobre los hosts descubiertos. Requiere -sS/-sU
//    (raw sockets); el Dockerfile de n8n_custom otorga el bit setuid a nmap
//    para que funcione con el usuario no privilegiado 'node'.
const portScanXml = await nmap(['-n', '-Pn', '--open', '-p', relevantPorts, '-sS', '-sU', '-sV', '-oX', '-', ...upIps]);

const hosts = [];
const psBlocks = portScanXml.match(/<host[\s>][\s\S]*?<\/host>/g) || [];
for (const block of psBlocks) {
  const ipMatch = block.match(/addr="([\d.]+)" addrtype="ipv4"/);
  if (!ipMatch) continue;
  const ip = ipMatch[1];
  const ports = [];
  const portBlocks = block.match(/<port protocol="(?:tcp|udp)" portid="\d+">[\s\S]*?<\/port>/g) || [];
  for (const pb of portBlocks) {
    const stateMatch = pb.match(/<state state="open"/);
    const portIdMatch = pb.match(/portid="(\d+)"/);
    if (stateMatch && portIdMatch) ports.push(parseInt(portIdMatch[1], 10));
  }
  hosts.push({ ip, ports });
}

return [{ json: { hosts, subnet, hostCount: hosts.length } }];
